UPDATE `result`
chip_time = #{chipTime}, net_time = #{netTime}, finish_status = #{finishStatus}, finish_time = #{finishTime},
WHERE id = #{id}

mapper.select:
SELECT res.id, res.registration_id, res.chip_time, res.net_time, res.finish_status, res.finish_time, rn.name AS runner_name, reg.bib_number AS bib_number, reg.event_id AS event_id, e.status AS event_status FROM `result` res INNER JOIN registration reg ON res.registration_id = reg.id INNER JOIN runner rn ON reg.runner_id = rn.id INNER JOIN marathon_event e ON reg.event_id = e.id
AND reg.event_id = #{eventId}
ORDER BY res.id DESC LIMIT #{pageSize} OFFSET #{offset}

SELECT 

WHERE reg.event_id = #{eventId}
AND res.finish_status = 1
AND rn.gender = #{gender}
ORDER BY res.net_time ASC, reg.bib_number ASC
